const { createClient } = require\(''@supabase/supabase-js''\);
const db = createClient\(
  ''https://dlzhwqlercetfgdntvzn.supabase.co'',
  ''eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImRsemh3cWxlcmNldGZnZG50dnpuIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3MTQyNzUyOSwiZXhwIjoyMDg3MDAzNTI5fQ.Ff8RqT8FiL0BdiJiV2Pzd0Yj85C8JXHsx-FkN3hj50Y'',
  { auth: { persistSession: false } }
\);

async function probar\(tabla, payload\) {
  const { data, error } = await db.from\(tabla\).insert\(payload\).select\(''id''\).single\(\);
  if \(error\) {
    console.log\(''❌ '' + tabla.padEnd\(18\) + '' — SIN secuencia: '' + error.message\);
  } else {
    console.log\(''✅ '' + tabla.padEnd\(18\) + '' — id auto-generado: '' + data.id\);
    await db.from\(tabla\).delete\(\).eq\(''id'', data.id\);
  }
}

async function run\(\) {
  // Necesitamos un cliente real para las tablas con FK
  const { data: cliente } = await db.from\(''clientes''\).insert\({ nombre: ''__TEST__'', estado: ''Cotizado'' }\).select\(''id''\).single\(\);
  const cid = cliente?.id;

  const { data: credito } = await db.from\(''creditos''\).insert\({ cliente: ''__TEST__'', monto: 1 }\).select\(''id''\).single\(\);
  const credId = credito?.id;

  await probar\(''pagos'',        { cliente_id: cid, monto: 1 }\);
  await probar\(''abonos'',       { credito_id: credId, monto: 1 }\);
  await probar\(''cotizaciones'', { cliente_id: cid, nombre: ''__TEST__'' }\);
  await probar\(''gestiones'',    { cliente_id: cid }\);
  await probar\(''plantillas'',   { nombre: ''__TEST__'', texto: ''__TEST__'' }\);
  await probar\(''audit_log'',    { action: ''TEST'', username: ''TEST'', ip: ''0.0.0.0'' }\);

  // Verificar usuarios
  const { data: uData, error: uErr } = await db.from\(''usuarios''\).select\(''username''\).limit\(1\);
  if \(uErr\) console.log\(''❌ usuarios       — error: '' + uErr.message\);
  else       console.log\(''✅ usuarios          — accesible \('' + \(uData?.length || 0\) + '' registros\)''\);

  // Limpiar cliente y credito de prueba
  if \(cid\)    await db.from\(''clientes''\).delete\(\).eq\(''id'', cid\);
  if \(credId\) await db.from\(''creditos''\).delete\(\).eq\(''id'', credId\);
}

run\(\).catch\(console.error\);
